import type {ToolDefinition} from '../../types/ai.js';
import {ToolRegistry} from './registry.js';

describe('specs/hal-engine-tool-input-validation/spec.md#7', () => {
  it('rejects missing fields from the current dynamic schema', async () => {
    const registry = new ToolRegistry();
    const executed: Record<string, unknown>[] = [];
    let inputSchema: ToolDefinition['inputSchema'] = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    registry.register(
      () => ({name: 'weather', description: 'Weather lookup', inputSchema}),
      async input => {
        executed.push(input);
        return JSON.stringify(input);
      }
    );
    const first = await registry.execute('weather', {});
    inputSchema = {type: 'object', properties: {city: {type: 'string'}}, required: ['city']};
    const second = await registry.execute('weather', {location: 'Berlin'});

    expect({first, second, executed}).toEqual({
      first: {result: expect.stringMatching(/required.*location|location.*required/i)},
      second: {result: expect.stringMatching(/required.*city|city.*required/i)},
      executed: [],
    });
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry-dynamic.test.ts --runInBand"
